package com.tutorhub.booking.controller; import com.tutorhub.booking.dto.*;import com.tutorhub.booking.service.BookingService;import com.tutorhub.common.security.CurrentUser;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/bookings") public class BookingController {private final BookingService service;private final CurrentUser current;public BookingController(BookingService s,CurrentUser c){service=s;current=c;}@PostMapping @ResponseStatus(HttpStatus.CREATED) BookingResponse create(@Valid @RequestBody CreateBookingRequest r){return service.create(current.require(),r);}@PostMapping("/recurring") @ResponseStatus(HttpStatus.CREATED) RecurringBookingResponse recurring(@Valid @RequestBody RecurringBookingRequest r){return service.recurring(current.require(),r);}@GetMapping("/mine") List<BookingResponse> mine(){return service.mine(current.require());}@GetMapping("/{id}") BookingResponse one(@PathVariable Long id){return service.one(id,current.require());}@PostMapping("/{id}/{action:confirm|cancel|complete|no-show}") BookingResponse action(@PathVariable Long id,@PathVariable String action,@RequestBody(required=false) Map<String,String> body){return service.action(current.require(),id,action,body==null?null:body.get("reason"));}}
